import React, { useState, useEffect } from 'react';
import { classNames } from 'primereact/utils';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';
import { ProductService } from './service/ProductService';


export default function ConditionalStyle() {
    const [products, setProducts] = useState([]);

    useEffect(() => {
        ProductService.getProductsMini().then((data) => setProducts(data));
    }, []);

    const rowClass = (data) => {
        return {
            'bg-primary fg-white': data.category === 'Fitness'
        };
    };

    const stockBodyTemplate = (rowData) => {
        const stockClassName = classNames('rds-circle w24 h24 fxb fvc fhc', {
            'bg-danger fg-white': rowData.quantity === 0,
            'bg-danger fg-white': rowData.quantity > 0 && rowData.quantity < 10,
            'bg-success fg-white': rowData.quantity > 10
        });

        return <div className={stockClassName}><span className="font-bold font-size12">{rowData.quantity}</span></div>;
    };

    return (
        <DataTable value={products} rowClassName={rowClass} tableStyle={{ minWidth: '50rem' }}>
            <Column field="code" header="Code"></Column>
            <Column field="name" header="Name"></Column>
            <Column field="category" header="Category"></Column>
            <Column field="quantity" header="Quantity" body={stockBodyTemplate}></Column>
        </DataTable>
    );

}